#!/bin/sh
# removes sessions older than 90d
psql "$SESSIONS_DB_URL" -c "DELETE FROM sessions WHERE last_seen < now() - interval '90 days';"

import re

PATTERNS = [re.compile(r'ignore (all )?previous instructions', re.I)]

def is_suspicious(text: str) -> bool:
    return any(p.search(text) for p in PATTERNS)
